<?php get_header(); ?><main class="site-main"><section class="page-hero"><div class="wrap"><div class="eyebrow">Archive</div><h1><?php the_archive_title(); ?></h1><?php the_archive_description('<p>','</p>'); ?></div></section><section><div class="wrap"><div class="posts-grid"><?php if(have_posts()): while(have_posts()): the_post(); ?><article class="post-card"><?php if(has_post_thumbnail()) the_post_thumbnail('large'); ?><div class="post-card-body"><time><?php echo esc_html(get_the_date()); ?></time><h3><a href="<?php the_permalink(); ?>"><?php the_title(); ?></a></h3><p><?php echo esc_html(get_the_excerpt()); ?></p></div></article><?php endwhile; endif; ?></div><?php the_posts_pagination(); ?></div></section></main><?php get_footer(); ?>